-- =============================================
-- IGCSE PHYSICS QUESTIONS - General Physics
-- =============================================

-- Motion Questions
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, syllabus_topic_id, exam_board_id, command_word) VALUES
('q_igcse_phy_001', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A car travels 150 km in 2.5 hours. What is its average speed?', 'calculation', NULL, '60 km/h', 'Average speed = distance / time = 150 km / 2.5 h = 60 km/h', 'easy', 3, 2, 'st_igcse_phy_1_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_002', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What is the difference between speed and velocity?', 'short_answer', NULL, 'Speed is a scalar quantity (magnitude only), while velocity is a vector quantity (magnitude and direction)', 'Speed is the rate of change of distance and has no direction. Velocity is the rate of change of displacement and includes direction.', 'easy', 3, 2, 'st_igcse_phy_1_2', 'board_cambridge', 'State'),
('q_igcse_phy_003', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A stone is dropped from a height. Its velocity increases by 10 m/s every second. What is the acceleration?', 'multiple_choice', '["A. 5 m/s²", "B. 10 m/s²", "C. 15 m/s²", "D. 20 m/s²"]', 'B', 'The acceleration is the rate of change of velocity. If velocity increases by 10 m/s every second, acceleration = 10 m/s².', 'easy', 3, 1, 'st_igcse_phy_1_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_004', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A cyclist accelerates from rest at 2 m/s² for 5 seconds. What is the final velocity?', 'calculation', NULL, '10 m/s', 'Using v = u + at, where u = 0, a = 2 m/s², t = 5s. v = 0 + (2 × 5) = 10 m/s', 'medium', 3, 2, 'st_igcse_phy_1_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_005', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Which of the following is a vector quantity?', 'multiple_choice', '["A. Speed", "B. Distance", "C. Time", "D. Velocity"]', 'D', 'Velocity is a vector because it has both magnitude and direction. Speed, distance, and time are scalars.', 'easy', 3, 1, 'st_igcse_phy_1_2', 'board_cambridge', 'Identify'),

-- Mass and Weight Questions
('q_igcse_phy_006', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What is the weight of a 5 kg object on Earth? (g = 10 N/kg)', 'calculation', NULL, '50 N', 'Weight = mass × gravitational field strength = 5 kg × 10 N/kg = 50 N', 'easy', 3, 2, 'st_igcse_phy_1_3', 'board_cambridge', 'Calculate'),
('q_igcse_phy_007', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Why does an astronaut weigh less on the Moon than on Earth?', 'short_answer', NULL, 'The gravitational field strength on the Moon is less than on Earth', 'Weight depends on gravitational field strength. The Moon has a smaller mass, so its gravitational field strength is about 1/6 of Earths.', 'medium', 3, 3, 'st_igcse_phy_1_3', 'board_cambridge', 'Explain'),
('q_igcse_phy_008', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Mass is measured in:', 'multiple_choice', '["A. Newtons", "B. Kilograms", "C. Metres per second", "D. Joules"]', 'B', 'Mass is measured in kilograms (kg). Newtons measure force/weight, m/s measures speed/velocity, Joules measure energy.', 'easy', 3, 1, 'st_igcse_phy_1_3', 'board_cambridge', 'State'),

-- Density Questions
('q_igcse_phy_009', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A block has a mass of 500 g and a volume of 200 cm³. Calculate its density.', 'calculation', NULL, '2.5 g/cm³', 'Density = mass / volume = 500 g / 200 cm³ = 2.5 g/cm³', 'easy', 3, 2, 'st_igcse_phy_1_4', 'board_cambridge', 'Calculate'),
('q_igcse_phy_010', 'topic_physics', 'subj_igcse_physics', 'igcse', 'An object floats in water. What can you conclude about its density compared to water?', 'multiple_choice', '["A. Greater than water", "B. Equal to water", "C. Less than water", "D. Cannot be determined"]', 'C', 'An object floats when its density is less than the density of the liquid. Water has a density of 1 g/cm³.', 'easy', 3, 1, 'st_igcse_phy_1_4', 'board_cambridge', 'State'),

-- Forces Questions
('q_igcse_phy_011', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A force of 20 N acts on an object of mass 4 kg. What is the acceleration?', 'calculation', NULL, '5 m/s²', 'Using F = ma, a = F/m = 20 N / 4 kg = 5 m/s²', 'medium', 3, 2, 'st_igcse_phy_1_5', 'board_cambridge', 'Calculate'),
('q_igcse_phy_012', 'topic_physics', 'subj_igcse_physics', 'igcse', 'State Newtons first law of motion.', 'short_answer', NULL, 'An object remains at rest or continues to move at constant velocity unless acted upon by a resultant force', 'This is also known as the law of inertia. Objects resist changes to their state of motion.', 'medium', 3, 2, 'st_igcse_phy_1_5', 'board_cambridge', 'State'),
('q_igcse_phy_013', 'topic_physics', 'subj_igcse_physics', 'igcse', 'The moment of a force depends on:', 'multiple_choice', '["A. Force only", "B. Distance from pivot only", "C. Both force and distance from pivot", "D. Neither force nor distance"]', 'C', 'Moment = Force × perpendicular distance from pivot. Both factors affect the turning effect.', 'medium', 3, 1, 'st_igcse_phy_1_5', 'board_cambridge', 'State'),
('q_igcse_phy_014', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Calculate the moment of a 40 N force acting at a distance of 0.5 m from a pivot.', 'calculation', NULL, '20 Nm', 'Moment = Force × distance = 40 N × 0.5 m = 20 Nm', 'easy', 3, 2, 'st_igcse_phy_1_5', 'board_cambridge', 'Calculate'),

-- Energy Questions
('q_igcse_phy_015', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A ball of mass 2 kg is lifted to a height of 5 m. Calculate the gravitational potential energy gained. (g = 10 N/kg)', 'calculation', NULL, '100 J', 'GPE = mgh = 2 kg × 10 N/kg × 5 m = 100 J', 'easy', 3, 2, 'st_igcse_phy_1_7', 'board_cambridge', 'Calculate'),
('q_igcse_phy_016', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A car has a kinetic energy of 40,000 J and a mass of 800 kg. Calculate its speed.', 'calculation', NULL, '10 m/s', 'KE = ½mv², so v² = 2KE/m = 2 × 40000 / 800 = 100, v = 10 m/s', 'medium', 3, 3, 'st_igcse_phy_1_7', 'board_cambridge', 'Calculate'),
('q_igcse_phy_017', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What is the principle of conservation of energy?', 'short_answer', NULL, 'Energy cannot be created or destroyed, only transferred from one form to another', 'The total energy in a closed system remains constant.', 'medium', 3, 2, 'st_igcse_phy_1_7', 'board_cambridge', 'State'),
('q_igcse_phy_018', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A machine has an efficiency of 80%. If the input energy is 500 J, what is the useful output energy?', 'calculation', NULL, '400 J', 'Efficiency = useful output / input × 100%. Output = 80% × 500 J = 400 J', 'medium', 3, 2, 'st_igcse_phy_1_7', 'board_cambridge', 'Calculate'),

-- Pressure Questions
('q_igcse_phy_019', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A force of 200 N acts on an area of 0.5 m². Calculate the pressure.', 'calculation', NULL, '400 Pa', 'Pressure = Force / Area = 200 N / 0.5 m² = 400 Pa', 'easy', 3, 2, 'st_igcse_phy_1_8', 'board_cambridge', 'Calculate'),
('q_igcse_phy_020', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Why do divers experience greater pressure at greater depths?', 'short_answer', NULL, 'The weight of water above them increases with depth, creating more pressure', 'Pressure in a liquid increases with depth due to the weight of the liquid column above.', 'medium', 3, 3, 'st_igcse_phy_1_8', 'board_cambridge', 'Explain'),

-- =============================================
-- IGCSE PHYSICS QUESTIONS - Thermal Physics
-- =============================================

('q_igcse_phy_021', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What are the three states of matter?', 'multiple_choice', '["A. Hot, warm, cold", "B. Solid, liquid, gas", "C. Fast, medium, slow", "D. Dense, medium, light"]', 'B', 'The three states of matter are solid, liquid, and gas, determined by the arrangement and motion of particles.', 'easy', 3, 1, 'st_igcse_phy_2_1', 'board_cambridge', 'State'),
('q_igcse_phy_022', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Describe the arrangement and motion of particles in a solid.', 'short_answer', NULL, 'Particles are closely packed in a regular pattern and vibrate about fixed positions', 'In solids, strong forces hold particles in fixed positions where they can only vibrate.', 'medium', 3, 3, 'st_igcse_phy_2_1', 'board_cambridge', 'Describe'),
('q_igcse_phy_023', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Calculate the energy needed to raise the temperature of 2 kg of water by 5°C. (Specific heat capacity of water = 4200 J/kg°C)', 'calculation', NULL, '42000 J', 'Energy = mcΔT = 2 kg × 4200 J/kg°C × 5°C = 42000 J', 'medium', 3, 3, 'st_igcse_phy_2_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_024', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Which method of heat transfer requires particles to move from place to place?', 'multiple_choice', '["A. Conduction", "B. Convection", "C. Radiation", "D. All of the above"]', 'B', 'Convection involves the bulk movement of fluid particles carrying thermal energy.', 'easy', 3, 1, 'st_igcse_phy_2_3', 'board_cambridge', 'State'),
('q_igcse_phy_025', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Explain why metals are good conductors of heat.', 'short_answer', NULL, 'Metals have free electrons that can move quickly and transfer kinetic energy throughout the material', 'Free electrons in metals can move rapidly, transferring energy much faster than in non-metals.', 'medium', 3, 3, 'st_igcse_phy_2_3', 'board_cambridge', 'Explain'),

-- =============================================
-- IGCSE PHYSICS QUESTIONS - Waves
-- =============================================

('q_igcse_phy_026', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A wave has a frequency of 50 Hz and a wavelength of 4 m. Calculate the wave speed.', 'calculation', NULL, '200 m/s', 'Wave speed = frequency × wavelength = 50 Hz × 4 m = 200 m/s', 'easy', 3, 2, 'st_igcse_phy_3_1', 'board_cambridge', 'Calculate'),
('q_igcse_phy_027', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What is the difference between transverse and longitudinal waves?', 'short_answer', NULL, 'In transverse waves, vibrations are perpendicular to the direction of travel. In longitudinal waves, vibrations are parallel to the direction of travel', 'Examples: transverse - light, water waves; longitudinal - sound', 'medium', 3, 3, 'st_igcse_phy_3_1', 'board_cambridge', 'Compare'),
('q_igcse_phy_028', 'topic_physics', 'subj_igcse_physics', 'igcse', 'The angle of incidence equals the angle of reflection. This is known as:', 'multiple_choice', '["A. Snells law", "B. Law of reflection", "C. Law of refraction", "D. Newtons law"]', 'B', 'The law of reflection states that the angle of incidence equals the angle of reflection.', 'easy', 3, 1, 'st_igcse_phy_3_2', 'board_cambridge', 'State'),
('q_igcse_phy_029', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What happens to light when it passes from air into glass?', 'multiple_choice', '["A. It speeds up and bends away from normal", "B. It slows down and bends towards normal", "C. It speeds up and bends towards normal", "D. Nothing happens"]', 'B', 'Light slows down in denser media and bends towards the normal when entering glass from air.', 'medium', 3, 1, 'st_igcse_phy_3_2', 'board_cambridge', 'State'),
('q_igcse_phy_030', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Which electromagnetic wave has the highest frequency?', 'multiple_choice', '["A. Radio waves", "B. Infrared", "C. Visible light", "D. Gamma rays"]', 'D', 'Gamma rays have the highest frequency in the electromagnetic spectrum.', 'easy', 3, 1, 'st_igcse_phy_3_3', 'board_cambridge', 'State'),

-- =============================================
-- IGCSE PHYSICS QUESTIONS - Electricity
-- =============================================

('q_igcse_phy_031', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Calculate the current when a charge of 60 C passes a point in 12 seconds.', 'calculation', NULL, '5 A', 'Current = Charge / Time = 60 C / 12 s = 5 A', 'easy', 3, 2, 'st_igcse_phy_4_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_032', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A resistor has a potential difference of 12 V and a current of 3 A. Calculate its resistance.', 'calculation', NULL, '4 Ω', 'Using Ohms Law: R = V/I = 12 V / 3 A = 4 Ω', 'easy', 3, 2, 'st_igcse_phy_4_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_033', 'topic_physics', 'subj_igcse_physics', 'igcse', 'In a series circuit, the total resistance is:', 'multiple_choice', '["A. Less than the smallest resistor", "B. Equal to the largest resistor", "C. The sum of all resistors", "D. The product divided by sum"]', 'C', 'In series, R_total = R1 + R2 + R3 + ...', 'easy', 3, 1, 'st_igcse_phy_4_3', 'board_cambridge', 'State'),
('q_igcse_phy_034', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Calculate the power of a device that uses 6 A at 240 V.', 'calculation', NULL, '1440 W', 'Power = Current × Voltage = 6 A × 240 V = 1440 W', 'easy', 3, 2, 'st_igcse_phy_4_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_035', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Why is electricity transmitted at high voltage?', 'short_answer', NULL, 'To reduce current and therefore reduce energy losses due to heating in the cables', 'P = I²R, so lower current means less power loss. P = IV is constant, so higher V means lower I.', 'hard', 3, 4, 'st_igcse_phy_4_5', 'board_cambridge', 'Explain'),

-- =============================================
-- IGCSE PHYSICS QUESTIONS - Nuclear Physics
-- =============================================

('q_igcse_phy_036', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What are the three types of radioactive decay?', 'multiple_choice', '["A. Alpha, beta, gamma", "B. Proton, neutron, electron", "C. Strong, weak, electromagnetic", "D. Fission, fusion, decay"]', 'A', 'The three main types of radioactive decay are alpha (α), beta (β), and gamma (γ).', 'easy', 3, 1, 'st_igcse_phy_5_2', 'board_cambridge', 'State'),
('q_igcse_phy_037', 'topic_physics', 'subj_igcse_physics', 'igcse', 'An alpha particle consists of:', 'multiple_choice', '["A. 2 protons and 2 neutrons", "B. 1 proton and 1 electron", "C. High-energy photon", "D. 2 electrons"]', 'A', 'An alpha particle is a helium nucleus with 2 protons and 2 neutrons.', 'easy', 3, 1, 'st_igcse_phy_5_2', 'board_cambridge', 'State'),
('q_igcse_phy_038', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A radioactive sample has a half-life of 4 hours. If you start with 80 g, how much remains after 12 hours?', 'calculation', NULL, '10 g', 'After 12 hours = 3 half-lives. 80 → 40 → 20 → 10 g', 'medium', 3, 3, 'st_igcse_phy_5_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_039', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Which type of radiation is most penetrating?', 'multiple_choice', '["A. Alpha", "B. Beta", "C. Gamma", "D. All equal"]', 'C', 'Gamma radiation is most penetrating, requiring thick lead or concrete to stop it.', 'easy', 3, 1, 'st_igcse_phy_5_2', 'board_cambridge', 'State'),
('q_igcse_phy_040', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What is the nucleon number of an atom with 92 protons and 146 neutrons?', 'calculation', NULL, '238', 'Nucleon number = protons + neutrons = 92 + 146 = 238', 'easy', 3, 1, 'st_igcse_phy_5_1', 'board_cambridge', 'Calculate'),

-- =============================================
-- IGCSE CHEMISTRY QUESTIONS
-- =============================================

('q_igcse_chem_001', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is the atomic number of an element?', 'multiple_choice', '["A. Number of neutrons", "B. Number of protons", "C. Number of electrons + neutrons", "D. Mass number"]', 'B', 'The atomic number is the number of protons in the nucleus of an atom.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_002', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Balance this equation: Mg + O₂ → MgO', 'short_answer', NULL, '2Mg + O₂ → 2MgO', 'We need 2 Mg atoms to balance the 2 oxygen atoms from O₂.', 'medium', 3, 2, NULL, 'board_cambridge', 'Balance'),
('q_igcse_chem_003', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What type of bonding is found in sodium chloride?', 'multiple_choice', '["A. Covalent", "B. Ionic", "C. Metallic", "D. Van der Waals"]', 'B', 'Sodium chloride has ionic bonding - electrons are transferred from sodium to chlorine.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_004', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Calculate the relative formula mass of H₂SO₄. (H=1, S=32, O=16)', 'calculation', NULL, '98', 'Mr = (2×1) + 32 + (4×16) = 2 + 32 + 64 = 98', 'medium', 3, 2, NULL, 'board_cambridge', 'Calculate'),
('q_igcse_chem_005', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is produced when an acid reacts with a metal carbonate?', 'multiple_choice', '["A. Salt + water", "B. Salt + water + carbon dioxide", "C. Salt + hydrogen", "D. Salt only"]', 'B', 'Acid + metal carbonate → salt + water + carbon dioxide', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_006', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Describe the test for hydrogen gas.', 'short_answer', NULL, 'A lighted splint makes a squeaky pop when placed near hydrogen gas', 'The pop sound is caused by hydrogen burning rapidly in air.', 'easy', 3, 2, NULL, 'board_cambridge', 'Describe'),
('q_igcse_chem_007', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is the pH of a neutral solution?', 'multiple_choice', '["A. 0", "B. 7", "C. 14", "D. 1"]', 'B', 'A neutral solution has pH 7. Acids have pH < 7, alkalis have pH > 7.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_008', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is the product at the cathode during electrolysis of molten sodium chloride?', 'multiple_choice', '["A. Chlorine", "B. Sodium", "C. Hydrogen", "D. Oxygen"]', 'B', 'Sodium ions (Na⁺) are attracted to the cathode and gain electrons to form sodium metal.', 'medium', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_009', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'State two factors that increase the rate of a chemical reaction.', 'short_answer', NULL, 'Increasing temperature, increasing concentration, using a catalyst, increasing surface area, increasing pressure (for gases)', 'Any two of these factors will increase the rate by increasing collision frequency or energy.', 'medium', 3, 2, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_010', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is the general formula for alkanes?', 'multiple_choice', '["A. CₙH₂ₙ", "B. CₙH₂ₙ₊₂", "C. CₙH₂ₙ₋₂", "D. CₙHₙ"]', 'B', 'Alkanes have the general formula CₙH₂ₙ₊₂. For example, methane is CH₄ (n=1).', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_011', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Which gas is produced during the thermal decomposition of calcium carbonate?', 'multiple_choice', '["A. Oxygen", "B. Hydrogen", "C. Carbon dioxide", "D. Nitrogen"]', 'C', 'CaCO₃ → CaO + CO₂. Carbon dioxide is released during thermal decomposition.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_012', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Explain why diamond and graphite have different properties despite both being carbon.', 'short_answer', NULL, 'They have different structures. Diamond has a tetrahedral structure with each carbon bonded to 4 others. Graphite has layers with each carbon bonded to 3 others with weak forces between layers.', 'The different arrangements of atoms give different properties.', 'hard', 3, 4, NULL, 'board_cambridge', 'Explain'),
('q_igcse_chem_013', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Calculate the number of moles in 44 g of carbon dioxide (CO₂). (C=12, O=16)', 'calculation', NULL, '1 mole', 'Mr of CO₂ = 12 + (2×16) = 44. Moles = mass/Mr = 44/44 = 1 mole', 'medium', 3, 2, NULL, 'board_cambridge', 'Calculate'),
('q_igcse_chem_014', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What colour change occurs when blue copper sulfate is heated?', 'multiple_choice', '["A. Blue to green", "B. Blue to white", "C. Blue to black", "D. No change"]', 'B', 'Hydrated copper sulfate (blue) loses water when heated to form anhydrous copper sulfate (white).', 'medium', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_015', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'In a reversible reaction at equilibrium, increasing the concentration of reactants will:', 'multiple_choice', '["A. Shift equilibrium to products", "B. Shift equilibrium to reactants", "C. Have no effect", "D. Stop the reaction"]', 'A', 'Le Chateliers principle: the system will shift to reduce the disturbance by producing more products.', 'medium', 3, 1, NULL, 'board_cambridge', 'Predict'),

-- =============================================
-- IGCSE BIOLOGY QUESTIONS
-- =============================================

('q_igcse_bio_001', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is the function of the nucleus in a cell?', 'multiple_choice', '["A. Produces energy", "B. Controls cell activities and contains genetic material", "C. Makes proteins", "D. Stores water"]', 'B', 'The nucleus contains DNA and controls all cell activities.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_002', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Name two organelles found only in plant cells.', 'short_answer', NULL, 'Cell wall and chloroplasts (also accept: large central vacuole)', 'These structures are unique to plant cells and are not found in animal cells.', 'easy', 3, 2, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_003', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is the word equation for photosynthesis?', 'short_answer', NULL, 'Carbon dioxide + water → glucose + oxygen (with light energy and chlorophyll)', 'Photosynthesis converts light energy to chemical energy in glucose.', 'easy', 3, 2, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_004', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Which blood vessel carries deoxygenated blood from the heart to the lungs?', 'multiple_choice', '["A. Pulmonary artery", "B. Pulmonary vein", "C. Aorta", "D. Vena cava"]', 'A', 'The pulmonary artery is unique - it carries deoxygenated blood from the right ventricle to the lungs.', 'medium', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_005', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is the role of enzymes in digestion?', 'short_answer', NULL, 'Enzymes are biological catalysts that speed up the breakdown of large food molecules into smaller, soluble molecules', 'Enzymes are specific and work best at particular temperatures and pH levels.', 'medium', 3, 3, NULL, 'board_cambridge', 'Explain'),
('q_igcse_bio_006', 'topic_biology', 'subj_igcse_biology', 'igcse', 'During aerobic respiration, glucose is broken down using:', 'multiple_choice', '["A. Carbon dioxide", "B. Oxygen", "C. Nitrogen", "D. Hydrogen"]', 'B', 'Aerobic respiration requires oxygen: glucose + oxygen → carbon dioxide + water + energy', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_007', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is osmosis?', 'short_answer', NULL, 'The net movement of water molecules from a region of higher water potential to a region of lower water potential through a partially permeable membrane', 'Osmosis is a special type of diffusion that only involves water molecules.', 'medium', 3, 3, NULL, 'board_cambridge', 'Define'),
('q_igcse_bio_008', 'topic_biology', 'subj_igcse_biology', 'igcse', 'In humans, how many chromosomes are in a normal body cell?', 'multiple_choice', '["A. 23", "B. 46", "C. 92", "D. 12"]', 'B', 'Human body cells have 46 chromosomes (23 pairs). Gametes have 23.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_009', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is the function of red blood cells?', 'multiple_choice', '["A. Fight infection", "B. Carry oxygen", "C. Blood clotting", "D. Carry nutrients"]', 'B', 'Red blood cells contain haemoglobin which binds to oxygen to transport it around the body.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_010', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Describe how adaptations of leaves help plants photosynthesise efficiently.', 'short_answer', NULL, 'Large surface area to absorb light, thin to allow gases to diffuse quickly, stomata for gas exchange, many chloroplasts in palisade cells, veins to transport water and glucose', 'Leaves are highly adapted organs for photosynthesis.', 'hard', 3, 5, NULL, 'board_cambridge', 'Describe'),
('q_igcse_bio_011', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What type of cell division produces gametes?', 'multiple_choice', '["A. Mitosis", "B. Meiosis", "C. Binary fission", "D. Budding"]', 'B', 'Meiosis produces gametes (sex cells) with half the chromosome number.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_012', 'topic_biology', 'subj_igcse_biology', 'igcse', 'If a tall plant (TT) is crossed with a short plant (tt), what is the ratio of tall to short in the F2 generation?', 'multiple_choice', '["A. 1:1", "B. 3:1", "C. 2:1", "D. All tall"]', 'B', 'F1 is all Tt (tall). F2 is TT:Tt:tt = 1:2:1, giving a 3 tall : 1 short ratio.', 'hard', 3, 2, NULL, 'board_cambridge', 'Predict'),
('q_igcse_bio_013', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is the role of the pancreas in digestion?', 'short_answer', NULL, 'The pancreas produces digestive enzymes (amylase, protease, lipase) and releases them into the small intestine. It also produces insulin to regulate blood glucose.', 'The pancreas has both digestive and hormonal functions.', 'medium', 3, 3, NULL, 'board_cambridge', 'Describe'),
('q_igcse_bio_014', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What happens during transpiration?', 'multiple_choice', '["A. Water enters roots", "B. Water evaporates from leaves", "C. Glucose is made", "D. Carbon dioxide is absorbed"]', 'B', 'Transpiration is the loss of water vapour from leaves through stomata.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_015', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Explain why exercise increases heart rate.', 'short_answer', NULL, 'During exercise, muscles need more oxygen and glucose for increased respiration to release energy. The heart beats faster to deliver more blood carrying these substances to the muscles and to remove waste products like carbon dioxide.', 'The cardiovascular system responds to increased metabolic demands.', 'medium', 3, 4, NULL, 'board_cambridge', 'Explain'),

-- =============================================
-- IGCSE MATHEMATICS QUESTIONS
-- =============================================

('q_igcse_math_001', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Simplify: 3x + 5x - 2x', 'calculation', NULL, '6x', 'Combine like terms: 3x + 5x - 2x = (3 + 5 - 2)x = 6x', 'easy', 3, 1, 'st_igcse_math_2_1', 'board_cambridge', 'Simplify'),
('q_igcse_math_002', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Factorise: x² + 5x + 6', 'calculation', NULL, '(x + 2)(x + 3)', 'Find two numbers that multiply to give 6 and add to give 5: 2 and 3.', 'medium', 3, 2, 'st_igcse_math_2_1', 'board_cambridge', 'Factorise'),
('q_igcse_math_003', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Solve: 2x + 7 = 15', 'calculation', NULL, 'x = 4', '2x = 15 - 7 = 8, so x = 8/2 = 4', 'easy', 3, 2, 'st_igcse_math_2_2', 'board_cambridge', 'Solve'),
('q_igcse_math_004', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Solve the simultaneous equations: x + y = 7 and x - y = 3', 'calculation', NULL, 'x = 5, y = 2', 'Adding equations: 2x = 10, so x = 5. Substituting: 5 + y = 7, so y = 2.', 'medium', 3, 3, 'st_igcse_math_2_2', 'board_cambridge', 'Solve'),
('q_igcse_math_005', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Find the nth term of the sequence: 3, 7, 11, 15, ...', 'calculation', NULL, '4n - 1', 'The common difference is 4. nth term = 4n + (3 - 4) = 4n - 1', 'medium', 3, 2, 'st_igcse_math_2_4', 'board_cambridge', 'Find'),
('q_igcse_math_006', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'What is the gradient of the line y = 3x + 2?', 'multiple_choice', '["A. 2", "B. 3", "C. 5", "D. 6"]', 'B', 'In y = mx + c form, m is the gradient. Here m = 3.', 'easy', 3, 1, 'st_igcse_math_2_6', 'board_cambridge', 'State'),
('q_igcse_math_007', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Calculate the area of a triangle with base 8 cm and height 5 cm.', 'calculation', NULL, '20 cm²', 'Area = ½ × base × height = ½ × 8 × 5 = 20 cm²', 'easy', 3, 2, 'st_igcse_math_4_1', 'board_cambridge', 'Calculate'),
('q_igcse_math_008', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Find the circumference of a circle with radius 7 cm. (Use π = 22/7)', 'calculation', NULL, '44 cm', 'Circumference = 2πr = 2 × (22/7) × 7 = 44 cm', 'easy', 3, 2, 'st_igcse_math_4_1', 'board_cambridge', 'Calculate'),
('q_igcse_math_009', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Calculate the volume of a cylinder with radius 3 cm and height 10 cm. (Use π = 3.14)', 'calculation', NULL, '282.6 cm³', 'Volume = πr²h = 3.14 × 3² × 10 = 3.14 × 9 × 10 = 282.6 cm³', 'medium', 3, 3, 'st_igcse_math_4_2', 'board_cambridge', 'Calculate'),
('q_igcse_math_010', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'In a right-angled triangle, if the opposite side is 3 cm and the hypotenuse is 5 cm, find sin θ.', 'calculation', NULL, '0.6 or 3/5', 'sin θ = opposite/hypotenuse = 3/5 = 0.6', 'easy', 3, 2, 'st_igcse_math_5_1', 'board_cambridge', 'Calculate'),
('q_igcse_math_011', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Use Pythagoras theorem to find the hypotenuse when the other sides are 6 cm and 8 cm.', 'calculation', NULL, '10 cm', 'c² = a² + b² = 36 + 64 = 100, so c = 10 cm', 'easy', 3, 2, 'st_igcse_math_5_1', 'board_cambridge', 'Calculate'),
('q_igcse_math_012', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'The mean of 5 numbers is 12. Four of the numbers are 10, 11, 13, 14. Find the fifth number.', 'calculation', NULL, '12', 'Sum = 5 × 12 = 60. Fifth number = 60 - (10+11+13+14) = 60 - 48 = 12', 'medium', 3, 3, 'st_igcse_math_6_2', 'board_cambridge', 'Calculate'),
('q_igcse_math_013', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'A bag contains 3 red balls and 5 blue balls. What is the probability of picking a red ball?', 'calculation', NULL, '3/8 or 0.375', 'P(red) = number of red / total = 3/(3+5) = 3/8', 'easy', 3, 2, 'st_igcse_math_6_3', 'board_cambridge', 'Calculate'),
('q_igcse_math_014', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Express 0.00045 in standard form.', 'calculation', NULL, '4.5 × 10⁻⁴', 'Move decimal 4 places right: 4.5 × 10⁻⁴', 'medium', 3, 1, 'st_igcse_math_1_4', 'board_cambridge', 'Write'),
('q_igcse_math_015', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Increase £240 by 15%.', 'calculation', NULL, '£276', '15% of 240 = 36. New amount = 240 + 36 = £276', 'easy', 3, 2, 'st_igcse_math_1_3', 'board_cambridge', 'Calculate'),
('q_igcse_math_016', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'If y is directly proportional to x, and y = 12 when x = 4, find y when x = 7.', 'calculation', NULL, '21', 'y = kx, so 12 = 4k, k = 3. When x = 7, y = 3 × 7 = 21', 'medium', 3, 3, 'st_igcse_math_1_5', 'board_cambridge', 'Calculate'),
('q_igcse_math_017', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Solve: x² - 5x + 6 = 0', 'calculation', NULL, 'x = 2 or x = 3', 'Factorising: (x-2)(x-3) = 0, so x = 2 or x = 3', 'medium', 3, 3, 'st_igcse_math_2_2', 'board_cambridge', 'Solve'),
('q_igcse_math_018', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'The angles in a triangle are in the ratio 2:3:4. Find the largest angle.', 'calculation', NULL, '80°', 'Sum = 180°. Parts = 2+3+4 = 9. Largest = (4/9) × 180 = 80°', 'medium', 3, 3, 'st_igcse_math_3_1', 'board_cambridge', 'Calculate'),
('q_igcse_math_019', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'What is the sum of interior angles of a hexagon?', 'calculation', NULL, '720°', 'Sum = (n-2) × 180 = (6-2) × 180 = 720°', 'medium', 3, 2, 'st_igcse_math_3_1', 'board_cambridge', 'Calculate'),
('q_igcse_math_020', 'topic_mathematics', 'subj_igcse_math', 'igcse', 'Simplify: (2x³)²', 'calculation', NULL, '4x⁶', '(2x³)² = 2² × (x³)² = 4x⁶', 'medium', 3, 2, 'st_igcse_math_1_4', 'board_cambridge', 'Simplify');

-- =============================================
-- More IGCSE PHYSICS QUESTIONS - Additional topics
-- =============================================

INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, syllabus_topic_id, exam_board_id, command_word) VALUES
('q_igcse_phy_041', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A car accelerates uniformly from 5 m/s to 25 m/s in 4 seconds. Calculate the acceleration.', 'calculation', NULL, '5 m/s²', 'a = (v-u)/t = (25-5)/4 = 20/4 = 5 m/s²', 'medium', 3, 2, 'st_igcse_phy_1_2', 'board_cambridge', 'Calculate'),
('q_igcse_phy_042', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What is meant by terminal velocity?', 'short_answer', NULL, 'The constant maximum velocity reached when the drag force equals the driving force or weight', 'At terminal velocity, the resultant force is zero and acceleration is zero.', 'medium', 3, 2, 'st_igcse_phy_1_2', 'board_cambridge', 'Define'),
('q_igcse_phy_043', 'topic_physics', 'subj_igcse_physics', 'igcse', 'A 2000 kg car travelling at 20 m/s brakes to a stop. Calculate the kinetic energy lost.', 'calculation', NULL, '400,000 J or 400 kJ', 'KE = ½mv² = ½ × 2000 × 20² = ½ × 2000 × 400 = 400,000 J', 'medium', 3, 3, 'st_igcse_phy_1_7', 'board_cambridge', 'Calculate'),
('q_igcse_phy_044', 'topic_physics', 'subj_igcse_physics', 'igcse', 'State Hookes Law.', 'short_answer', NULL, 'The extension of a spring is directly proportional to the applied force, provided the limit of proportionality is not exceeded', 'F = kx, where k is the spring constant.', 'medium', 3, 2, 'st_igcse_phy_1_5', 'board_cambridge', 'State'),
('q_igcse_phy_045', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Calculate the momentum of a 1500 kg car travelling at 12 m/s.', 'calculation', NULL, '18,000 kg m/s', 'Momentum = mass × velocity = 1500 × 12 = 18,000 kg m/s', 'easy', 3, 2, 'st_igcse_phy_1_6', 'board_cambridge', 'Calculate'),
('q_igcse_phy_046', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Two objects collide and stick together. What type of collision is this?', 'multiple_choice', '["A. Elastic", "B. Inelastic", "C. Nuclear", "D. Explosive"]', 'B', 'In an inelastic collision, kinetic energy is not conserved (some is converted to other forms).', 'medium', 3, 1, 'st_igcse_phy_1_6', 'board_cambridge', 'State'),
('q_igcse_phy_047', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What happens to the pressure in a liquid as depth increases?', 'multiple_choice', '["A. Decreases", "B. Increases", "C. Stays the same", "D. Becomes zero"]', 'B', 'Pressure increases with depth due to the weight of liquid above. P = hρg', 'easy', 3, 1, 'st_igcse_phy_1_8', 'board_cambridge', 'State'),
('q_igcse_phy_048', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Calculate the pressure at a depth of 5 m in water. (Density of water = 1000 kg/m³, g = 10 N/kg)', 'calculation', NULL, '50,000 Pa or 50 kPa', 'P = hρg = 5 × 1000 × 10 = 50,000 Pa', 'medium', 3, 2, 'st_igcse_phy_1_8', 'board_cambridge', 'Calculate'),
('q_igcse_phy_049', 'topic_physics', 'subj_igcse_physics', 'igcse', 'What is the specific latent heat of fusion?', 'short_answer', NULL, 'The energy required to change 1 kg of a substance from solid to liquid at constant temperature', 'During melting, energy is used to break bonds between particles, not to increase temperature.', 'medium', 3, 2, 'st_igcse_phy_2_2', 'board_cambridge', 'Define'),
('q_igcse_phy_050', 'topic_physics', 'subj_igcse_physics', 'igcse', 'Calculate the energy needed to melt 2 kg of ice at 0°C. (Lf = 334,000 J/kg)', 'calculation', NULL, '668,000 J or 668 kJ', 'E = mL = 2 × 334,000 = 668,000 J', 'medium', 3, 2, 'st_igcse_phy_2_2', 'board_cambridge', 'Calculate');

-- =============================================
-- More IGCSE CHEMISTRY QUESTIONS
-- =============================================

INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, syllabus_topic_id, exam_board_id, command_word) VALUES
('q_igcse_chem_016', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is an isotope?', 'short_answer', NULL, 'Atoms of the same element with the same number of protons but different numbers of neutrons', 'Isotopes have the same atomic number but different mass numbers.', 'medium', 3, 2, NULL, 'board_cambridge', 'Define'),
('q_igcse_chem_017', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Draw a dot-and-cross diagram for water (H₂O).', 'diagram', NULL, 'Oxygen in center with 2 lone pairs, each hydrogen sharing one electron with oxygen', 'Water has 2 covalent bonds and 2 lone pairs on oxygen.', 'medium', 3, 3, NULL, 'board_cambridge', 'Draw'),
('q_igcse_chem_018', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Why do ionic compounds have high melting points?', 'short_answer', NULL, 'There are strong electrostatic forces of attraction between oppositely charged ions which require a lot of energy to break', 'The giant ionic lattice structure requires significant energy to disrupt.', 'medium', 3, 3, NULL, 'board_cambridge', 'Explain'),
('q_igcse_chem_019', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Calculate the percentage by mass of oxygen in CO₂. (C=12, O=16)', 'calculation', NULL, '72.7%', 'Mr = 44. Mass of O = 32. Percentage = (32/44) × 100 = 72.7%', 'medium', 3, 3, NULL, 'board_cambridge', 'Calculate'),
('q_igcse_chem_020', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is the test for chlorine gas?', 'multiple_choice', '["A. Relights glowing splint", "B. Pop with lighted splint", "C. Bleaches damp litmus paper", "D. Turns limewater milky"]', 'C', 'Chlorine bleaches damp litmus paper (turns it white).', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_021', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'In the Haber process, what are the raw materials?', 'multiple_choice', '["A. Nitrogen and hydrogen", "B. Nitrogen and oxygen", "C. Ammonia and water", "D. Nitrogen and carbon dioxide"]', 'A', 'N₂ + 3H₂ ⇌ 2NH₃ (with iron catalyst, 450°C, 200 atm)', 'medium', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_022', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What is the name of the process where crude oil is separated into fractions?', 'multiple_choice', '["A. Cracking", "B. Fractional distillation", "C. Polymerisation", "D. Combustion"]', 'B', 'Fractional distillation separates crude oil based on different boiling points.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_023', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Write the balanced equation for the complete combustion of methane.', 'short_answer', NULL, 'CH₄ + 2O₂ → CO₂ + 2H₂O', 'Complete combustion produces carbon dioxide and water.', 'medium', 3, 2, NULL, 'board_cambridge', 'Write'),
('q_igcse_chem_024', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'What type of reaction occurs when ethene reacts with bromine water?', 'multiple_choice', '["A. Substitution", "B. Addition", "C. Elimination", "D. Combustion"]', 'B', 'Alkenes undergo addition reactions. The bromine adds across the double bond.', 'medium', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_chem_025', 'topic_chemistry', 'subj_igcse_chemistry', 'igcse', 'Name the products when zinc reacts with hydrochloric acid.', 'short_answer', NULL, 'Zinc chloride and hydrogen', 'Zn + 2HCl → ZnCl₂ + H₂. A salt and hydrogen are produced.', 'easy', 3, 2, NULL, 'board_cambridge', 'State');

-- =============================================
-- More IGCSE BIOLOGY QUESTIONS
-- =============================================

INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, syllabus_topic_id, exam_board_id, command_word) VALUES
('q_igcse_bio_016', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is active transport?', 'short_answer', NULL, 'The movement of molecules against a concentration gradient, requiring energy from respiration', 'Active transport moves substances from low to high concentration.', 'medium', 3, 3, NULL, 'board_cambridge', 'Define'),
('q_igcse_bio_017', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Name the enzyme that digests starch.', 'multiple_choice', '["A. Protease", "B. Lipase", "C. Amylase", "D. Catalase"]', 'C', 'Amylase breaks down starch into maltose.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_018', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Where does gas exchange occur in the lungs?', 'multiple_choice', '["A. Trachea", "B. Bronchi", "C. Bronchioles", "D. Alveoli"]', 'D', 'Alveoli have thin walls, good blood supply, and large surface area for efficient gas exchange.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_019', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Describe the structure and function of arteries.', 'short_answer', NULL, 'Arteries have thick muscular walls and narrow lumen. They carry blood away from the heart at high pressure.', 'The elastic walls can stretch and recoil to maintain blood pressure.', 'medium', 3, 4, NULL, 'board_cambridge', 'Describe'),
('q_igcse_bio_020', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is the function of valves in veins?', 'multiple_choice', '["A. Speed up blood flow", "B. Prevent backflow of blood", "C. Increase blood pressure", "D. Filter the blood"]', 'B', 'Valves prevent backflow of blood as veins carry blood at low pressure.', 'easy', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_021', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is the word equation for anaerobic respiration in humans?', 'short_answer', NULL, 'Glucose → lactic acid (+ energy)', 'Anaerobic respiration occurs without oxygen and produces lactic acid in muscles.', 'medium', 3, 2, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_022', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Name the hormone that controls blood glucose levels.', 'multiple_choice', '["A. Adrenaline", "B. Insulin", "C. Glucagon", "D. Both B and C"]', 'D', 'Insulin lowers blood glucose, glucagon raises it. Both are produced by the pancreas.', 'medium', 3, 1, NULL, 'board_cambridge', 'State'),
('q_igcse_bio_023', 'topic_biology', 'subj_igcse_biology', 'igcse', 'What is natural selection?', 'short_answer', NULL, 'The process where organisms with advantageous characteristics are more likely to survive and reproduce, passing on their genes', 'This leads to evolution over many generations.', 'hard', 3, 4, NULL, 'board_cambridge', 'Explain'),
('q_igcse_bio_024', 'topic_biology', 'subj_igcse_biology', 'igcse', 'A food chain shows: Grass → Rabbit → Fox. Which organism is the secondary consumer?', 'multiple_choice', '["A. Grass", "B. Rabbit", "C. Fox", "D. Sun"]', 'C', 'Fox is the secondary consumer (eats the primary consumer, rabbit).', 'easy', 3, 1, NULL, 'board_cambridge', 'Identify'),
('q_igcse_bio_025', 'topic_biology', 'subj_igcse_biology', 'igcse', 'Explain why energy is lost between trophic levels.', 'short_answer', NULL, 'Energy is lost through respiration, excretion, and in uneaten parts of organisms. Only about 10% of energy passes to the next level.', 'This limits the length of food chains.', 'hard', 3, 4, NULL, 'board_cambridge', 'Explain');
